var matchBriefMarkup=null,matchBriefHost=null;
function renderMatchBrief(){
 if(view!=='match'||matchPopupActive!=='brief'||!state)return;
 const pending=motionEnabled()&&lastEvent&&['goal','shot','chance'].includes(lastEvent.type)&&!lastEventFast&&(movementEvent!==lastEvent||movementEventAge<Movement.impactAge(lastEvent))?lastEvent:null;
 const d=MatchBrief.read(state,{pendingEvent:pending}),host=$('match-popup-brief');if(!host||!d.valid)return;
 const esc=escapeText,bars=d.flow.windows.map((w,i)=>'<li'+(i===d.flow.active?' aria-current="true"':'')+'><span aria-label="'+w.from+'~'+w.to+'분 우리 '+w.own+' 상대 '+w.opponent+'"><i style="height:'+Math.round(w.own/d.flow.scale*100)+'%"></i><i style="height:'+Math.round(w.opponent/d.flow.scale*100)+'%"></i></span><small>'+w.to+'′</small></li>').join('');
 const hero=d.hero?Portraits.html(F.identityProfile(d.hero.identity))+'<span><b>'+esc(d.hero.name)+'</b><small>현재 우리 팀 최다 '+d.hero.goals+'골</small></span>':StaffPortraits.html({name:'수석 코치'})+'<span><b>'+ (d.shared?'함께 만든 득점':'코치의 경기 수첩')+'</b><small>현재 평균 체력 '+d.energy+' · 남은 교체 '+d.remaining+'명</small></span>';
 const html='<article class="match-brief"><header>'+ClubArt.moment(d.art)+'<div><small>'+d.minute+'분 · '+(d.phase==='full'?'90분 기록 · 확정 전':'현재 보이는 기록')+'</small><h3>'+esc(d.title)+'</h3><strong>우리 '+d.score[0]+' : '+d.score[1]+' 상대</strong></div></header><div class="brief-stats">'+d.stats.map(s=>'<div><small>'+s.label+'</small><b>'+s.values[0]+' : '+s.values[1]+'</b></div>').join('')+'</div><section class="brief-flow"><div><b>15분별 공격 흐름</b><span><i></i>우리 <i></i>상대</span></div><ol>'+bars+'</ol><small>기회·슈팅·골 가중치 · '+(d.pending?'재생 중 장면 결과 제외':d.limited?'기록된 구간만 표시':'기록 기반')+'</small></section><section class="brief-person">'+hero+'</section><ol class="brief-moments">'+(d.moments.length?d.moments.map(e=>'<li><b>'+e.minute+'′</b><span>'+esc(e.text)+'</span></li>').join(''):'<li>슈팅·득점·카드 장면이 여기에 남습니다.</li>')+'</ol><section class="brief-advice"><b>'+esc(d.advice.title)+'</b><p>'+esc(d.advice.text)+'</p></section><div class="brief-actions"><button type="button" data-brief-target="'+d.advice.target+'">'+esc(d.advice.label)+'</button>'+(d.advice.target!=='stats'?'<button type="button" class="secondary" data-brief-target="stats">상세 통계</button>':'')+'</div></article>';
 if(matchBriefHost===host&&matchBriefMarkup===html)return;host.innerHTML=html;matchBriefHost=host;matchBriefMarkup=html;
 host.onclick=e=>{const b=e.target.closest('[data-brief-target]');if(b){if(b.dataset.briefTarget==='roster'&&d.advice.playerId&&state.lineup.includes(d.advice.playerId))selected=d.advice.playerId;openMatchPopup(b.dataset.briefTarget,b);}};
}
const briefOriginalPopup=renderMatchPopup;renderMatchPopup=function(){briefOriginalPopup();renderMatchBrief();};
